CREATE OR REPLACE FUNCTION public.abrir_venta(p_lineas jsonb, p_ubicacion_id bigint, p_sesion_caja_id bigint, p_pagos jsonb DEFAULT NULL::jsonb, p_cliente_id bigint DEFAULT NULL::bigint, p_descuento_total numeric DEFAULT 0, p_usuario text DEFAULT NULL::text, p_idempotencia text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
declare
  v_venta_id   bigint;
  v_numero     text;
  v_anio       int;
  v_linea      jsonb;
  v_prod       bigint;
  v_unit       numeric;
  v_lista      numeric;
  v_pres       bigint;
  v_pres_base  bigint;
  v_factor     numeric;
  v_cant       numeric;
  v_cant_pres  numeric;
  v_sub        numeric;
  v_subtotal   numeric := 0;
  v_total      numeric;
  v_pagado     numeric := 0;
  v_pago       jsonb;
  v_previa     jsonb;
  v_tipo_prec  text;
  v_hay_pagos  boolean;
begin
  -- ── Validaciones de entrada ────────────────────────────────────────
  if jsonb_typeof(p_lineas) <> 'array' or jsonb_array_length(p_lineas) = 0 then
    raise exception 'p_lineas debe ser un array no vacío';
  end if;

  v_hay_pagos := p_pagos is not null
                 and jsonb_typeof(p_pagos) = 'array'
                 and jsonb_array_length(p_pagos) > 0;

  -- ── Idempotencia (mismo patrón que registrar_venta) ────────────────
  if p_idempotencia is not null then
    if btrim(p_idempotencia) = '' or length(p_idempotencia) > 200 then
      raise exception 'Clave de idempotencia inválida (vacía, en blanco, o mayor a 200 caracteres)';
    end if;
    perform pg_advisory_xact_lock(hashtextextended('venta:' || p_idempotencia, 0));
    select jsonb_build_object('venta_id', v.id, 'numero', v.numero, 'subtotal', v.subtotal,
             'descuento_total', v.descuento_total, 'total', v.total,
             'estado', v.estado, 'reintento', true)
      into v_previa
      from venta v
     where v.idempotencia_clave = p_idempotencia;
    if v_previa is not null then
      return v_previa;
    end if;
  end if;

  -- ── Sesión de caja abierta ─────────────────────────────────────────
  perform 1 from sesion_caja where id = p_sesion_caja_id and estado = 'ABIERTA';
  if not found then
    raise exception 'No hay una sesión de caja abierta (%).', p_sesion_caja_id;
  end if;

  -- ── Ubicación explícita y real ─────────────────────────────────────
  if p_ubicacion_id is null then
    raise exception 'p_ubicacion_id es obligatorio: define de dónde saldrá la mercadería';
  end if;
  perform 1 from ubicacion where id = p_ubicacion_id;
  if not found then
    raise exception 'La ubicación % no existe', p_ubicacion_id;
  end if;

  -- ── Regla retail ───────────────────────────────────────────────────
  if p_cliente_id is not null then
    select c.tipo_precio::text into v_tipo_prec from cliente c where c.id = p_cliente_id;
    if v_tipo_prec is null then
      raise exception 'El cliente % no existe', p_cliente_id;
    end if;
    if v_tipo_prec in ('institucion', 'corporativo', 'mayorista') then
      raise exception
        'La venta directa es solo para retail. El cliente % es % y requiere pedido con cotización previa.',
        p_cliente_id, v_tipo_prec;
    end if;
  end if;

  -- ── Numeración propia (B1): serie VTD-2026-NNNNN, año en La Paz ────
  v_anio := extract(year from now() at time zone 'America/La_Paz')::int;
  v_numero := formato_numero('VTD', v_anio, siguiente_numero('VTD', v_anio));

  -- ── Cabecera ───────────────────────────────────────────────────────
  insert into venta (numero, cliente_id, ubicacion_id, estado, creado_por,
                     sesion_caja_id, idempotencia_clave, descuento_total)
  values (v_numero, p_cliente_id, p_ubicacion_id, 'ABIERTA', p_usuario,
          p_sesion_caja_id, p_idempotencia, coalesce(p_descuento_total, 0))
  returning id into v_venta_id;

  -- ── Líneas (sin tocar Kardex) ──────────────────────────────────────
  for v_linea in select * from jsonb_array_elements(p_lineas) loop
    v_prod  := (v_linea->>'producto_id')::bigint;
    v_unit  := (v_linea->>'precio_unitario')::numeric;
    v_lista := coalesce((v_linea->>'precio_lista')::numeric, v_unit);
    v_pres  := (v_linea->>'presentacion_id')::bigint;

    if v_prod is null or v_unit is null then
      raise exception 'Línea inválida (producto_id/precio_unitario)';
    end if;

    select id into v_pres_base from presentacion
     where producto_id = v_prod and es_base = true and coalesce(activo, true) = true
     limit 1;
    if v_pres_base is null then
      raise exception 'Producto % sin presentación base', v_prod;
    end if;

    if v_pres is not null then
      select factor_unidad_base into v_factor from presentacion
       where id = v_pres and producto_id = v_prod and coalesce(activo, true);
      if v_factor is null then
        raise exception 'La presentación % no pertenece al producto % (o está inactiva)', v_pres, v_prod;
      end if;
      v_cant_pres := (v_linea->>'cantidad_presentacion')::numeric;
      if v_cant_pres is null or v_cant_pres <= 0 then
        raise exception 'cantidad_presentacion debe ser positiva';
      end if;
      v_cant := v_cant_pres * v_factor;
    else
      v_pres      := v_pres_base;
      v_cant      := coalesce((v_linea->>'cantidad_base')::numeric, (v_linea->>'cantidad')::numeric);
      v_cant_pres := v_cant;
    end if;

    if v_cant is null or v_cant <= 0 then
      raise exception 'cantidad debe ser positiva';
    end if;

    v_sub := round(v_unit * v_cant_pres, 2);

    -- kardex_transaccion_id queda NULL: lo llenará completar_venta.
    -- subtotal y precio_modificado son GENERATED: excluidas del INSERT.
    insert into venta_linea (venta_id, producto_id, presentacion_id, cantidad,
                             cantidad_presentacion, precio_lista, precio_unitario)
    values (v_venta_id, v_prod, v_pres, v_cant, v_cant_pres, v_lista, v_unit);

    v_subtotal := v_subtotal + v_sub;
  end loop;

  v_total := round(v_subtotal - coalesce(p_descuento_total, 0), 2);

  -- ── Pagos: solo en modo precobrado ─────────────────────────────────
  if v_hay_pagos then
    select coalesce(sum((p->>'monto')::numeric), 0) into v_pagado
      from jsonb_array_elements(p_pagos) p;
    if round(v_pagado, 2) <> v_total then
      raise exception 'El pago (%) no coincide con el total (%)', v_pagado, v_total;
    end if;

    for v_pago in select * from jsonb_array_elements(p_pagos) loop
      insert into venta_pago (venta_id, metodo, monto)
      values (v_venta_id, (v_pago->>'metodo')::metodo_pago, (v_pago->>'monto')::numeric);

      insert into movimiento_caja (sesion_caja_id, tipo, metodo, monto, venta_id, creado_por)
      values (p_sesion_caja_id, 'VENTA', (v_pago->>'metodo')::metodo_pago,
              (v_pago->>'monto')::numeric, v_venta_id, p_usuario);
    end loop;
  end if;

  -- Se guardan los totales calculados. completar_venta los recalcula al
  -- cerrar, así que si las líneas se ajustan en el medio, el total final
  -- sigue siendo correcto sin intervención manual.
  update venta
     set subtotal = v_subtotal,
         total    = v_total
   where id = v_venta_id;

  return jsonb_build_object(
    'venta_id',        v_venta_id,
    'numero',          v_numero,
    'estado',          'ABIERTA',
    'modo',            case when v_hay_pagos then 'PRECOBRADO' else 'POSTCOBRADO' end,
    'subtotal',        v_subtotal,
    'descuento_total', coalesce(p_descuento_total, 0),
    'total',           v_total,
    'pagado',          v_pagado,
    'ubicacion_id',    p_ubicacion_id
  );
end;
$function$
